import{_ as s,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"31 | 多Agent协作系统构建：让Agent团队分工协作","description":"","frontmatter":{},"headers":[{"level":2,"title":"理解 SubAgent 机制：四大模块","slug":"理解-subagent-机制-四大模块","link":"#理解-subagent-机制-四大模块","children":[]},{"level":2,"title":"实战：内容生产流水线","slug":"实战-内容生产流水线","link":"#实战-内容生产流水线","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"OpenClaw核心原理与实战/31｜多Agent协作系统构建：让Agent团队分工协作.md","filePath":"OpenClaw核心原理与实战/31｜多Agent协作系统构建：让Agent团队分工协作.md","lastUpdated":1795533128000}'),t={name:"OpenClaw核心原理与实战/31｜多Agent协作系统构建：让Agent团队分工协作.md"};function l(i,n,o,c,g,r){return a(),e("div",null,[...n[0]||(n[0]=[p(`<h1 id="_31-多agent协作系统构建-让agent团队分工协作" tabindex="-1">31 | 多Agent协作系统构建：让Agent团队分工协作 <a class="header-anchor" href="#_31-多agent协作系统构建-让agent团队分工协作" aria-label="Permalink to &quot;31 | 多Agent协作系统构建：让Agent团队分工协作&quot;">​</a></h1><p>你好，我是 Henry，欢迎来到《OpenClaw 核心原理与实战》。</p><p>上节课我们完成了一个包含两个 Agent 的运营助手项目。analyst 处理数据分析，customer-bot 处理客服问题，它们各自独立工作，互不干扰。但如果一个任务太复杂，比如：“帮我写一篇关于 AI 发展趋势的深度报告。” 这个任务涉及信息收集、数据分析、内容撰写、质量审校。让一个 Agent 独立完成这四步，它会陷入一个超长的推理循环，上下文窗口很快被填满，推理质量也会随着对话变长而下降。真正高效的方案是分工协作，像一个内容团队。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/1.png" alt=""></a></p><p>多 Agent 协作是 AI Agent 从“工具”进化为“团队”的关键能力。受限于上下文窗口、单线程推理、以及固定的角色定位，单 Agent 能做的事有上限。多 Agent 协作打破了这些限制。这就是 OpenClaw 的 SubAgent 动态协作机制，今天我们要把这个机制从理论变成实践。</p><h2 id="理解-subagent-机制-四大模块" tabindex="-1">理解 SubAgent 机制：四大模块 <a class="header-anchor" href="#理解-subagent-机制-四大模块" aria-label="Permalink to &quot;理解 SubAgent 机制：四大模块&quot;">​</a></h2><p>Subagent 机制的配置和使用中有很多坑，比如子 Agent 的工具权限为什么被自动收紧了？为什么某个子 Agent 的结果没有正确回传？这些问题的答案都在四大模块设计中。</p><p>Subagent 系统由 spawn、registry、control、announce 四个模块组成。用一个比喻来理解四个模块的关系，假如你是一家公司的 CEO（父 Agent），你要安排员工（子 Agent）完成工作。</p><ul><li><p>spawn（招聘）：面试候选人（权限检查），确认他能胜任（验证），然后发 offer 让他入职（启动）</p></li><li><p>registry（花名册）：HR 维护所有在职员工的记录，谁在做什么任务、状态怎样，员工离职了自动从花名册删除（孤儿回收）</p></li><li><p>control（管理）：随时可以查看员工的工作进度，也可以叫停某个人的任务（取消）</p></li><li><p>announce（汇报）：员工完成任务后，把成果汇报给你。你汇总所有人的成果，输出最终交付物</p></li></ul><p>OpenClaw 支持两种子 Agent 运行模式：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/2.png" alt=""></a></p><p>今天我们主要使用 run 模式，因为内容生产流水线中的子任务都是“做完就走”的性质。</p><p>OpenClaw 安全机制采用子 Agent 权限自动收紧策略，OpenClaw 为子 Agent 定义了独立的拒绝列表。</p><p>所有子 Agent 一律禁止的工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gateway、agents_list、whatsapp_login，系统管理类</span></span>
<span class="line"><span>session_status、cron，应由父 Agent 管理</span></span>
<span class="line"><span>memory_search、memory_get，内存工具应通过 spawn prompt 传递</span></span>
<span class="line"><span>sessions_send，防止跨 Session 注入</span></span></code></pre></div><p>叶子 Agent 额外禁止的工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>subagents、sessions_spawn，不能再创建下级</span></span>
<span class="line"><span>sessions_list、sessions_history，不需要查看其他会话</span></span>
<span class="line"><span>整体原则是每一层只能收紧，不能放宽。父 Agent 有 exec 权限不代表子 Agent 也有。子</span></span></code></pre></div><p>Agent 被 Prompt Injection 攻击时，因为权限被大幅收窄，攻击面非常有限。</p><h2 id="实战-内容生产流水线" tabindex="-1">实战：内容生产流水线 <a class="header-anchor" href="#实战-内容生产流水线" aria-label="Permalink to &quot;实战：内容生产流水线&quot;">​</a></h2><p>回顾了 Subagent 机制后，我们进入实战环节，构建一个内容生产流水线，包含四个 Agent：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/3.png" alt=""></a></p><p>模型选型方案，参照模型优先级链的实际应用，不同角色使用不同模型，既保障了质量，又控制了成本：</p><ul><li><p>总监用 claude-sonnet：需要分析复杂任务、拆解子任务、汇总多方信息，这些都需要强推理能力</p></li><li><p>调研员用 gpt-4o-mini：信息收集是相对标准化的任务，不需要顶级推理能力，用经济模型降低成本</p></li><li><p>撰稿人用 gpt-4o：内容创作需要较好的语言表达能力，gpt-4o 在写作方面表现优秀</p></li><li><p>审校员用 claude-sonnet：审校需要严格的逻辑推理和事实判断能力</p></li></ul><p>详细的完整配置如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># openclaw.yaml — 内容生产流水线</span></span>
<span class="line"><span>providers:</span></span>
<span class="line"><span> default: openai</span></span>
<span class="line"><span> openai:</span></span>
<span class="line"><span>   apiKey: &quot;\${OPENAI_API_KEY}&quot;</span></span>
<span class="line"><span> anthropic:</span></span>
<span class="line"><span>   apiKey: &quot;\${ANTHROPIC_API_KEY}&quot;</span></span>
<span class="line"><span>agents:</span></span>
<span class="line"><span> list:</span></span>
<span class="line"><span>   # 内容总监 — 任务拆解和结果汇总</span></span>
<span class="line"><span>   - id: director</span></span>
<span class="line"><span>     model: claude-sonnet-4-20250514</span></span>
<span class="line"><span>     identity:</span></span>
<span class="line"><span>       name: &quot;内容总监&quot;</span></span>
<span class="line"><span>       instructions: |</span></span>
<span class="line"><span>         你是内容团队的总监。当收到内容创作需求时：</span></span>
<span class="line"><span>         1. 分析需求，拆解为三个子任务：</span></span>
<span class="line"><span>            - research（调研）：收集相关信息和数据</span></span>
<span class="line"><span>            - write（写作）：基于调研结果撰写文章</span></span>
<span class="line"><span>            - review（审校）：检查事实准确性和行文质量</span></span>
<span class="line"><span>         2. 依次 spawn 子 Agent 完成每个子任务</span></span>
<span class="line"><span>         3. 收到所有子 Agent 的结果后，汇总输出最终稿件</span></span>
<span class="line"><span>         注意事项：</span></span>
<span class="line"><span>         - 给每个子 Agent 的 prompt 要明确、具体</span></span>
<span class="line"><span>         - 写作任务要附上调研结果作为参考素材</span></span>
<span class="line"><span>         - 审校任务要附上文章全文和调研数据用于核实</span></span>
<span class="line"><span>     subagents:</span></span>
<span class="line"><span>       allowAgents: [&quot;researcher&quot;, &quot;writer&quot;, &quot;reviewer&quot;]</span></span>
<span class="line"><span>       model: gpt-4o-mini    # 子 Agent 默认使用经济模型</span></span>
<span class="line"><span>     tools:</span></span>
<span class="line"><span>       allow: [&quot;*&quot;]</span></span>
<span class="line"><span>   # 调研员 — 信息收集和事实核查</span></span>
<span class="line"><span>   - id: researcher</span></span>
<span class="line"><span>     model: gpt-4o-mini</span></span>
<span class="line"><span>     identity:</span></span>
<span class="line"><span>       name: &quot;调研员&quot;</span></span>
<span class="line"><span>       instructions: |</span></span>
<span class="line"><span>         你是一位严谨的调研员。你的工作是：</span></span>
<span class="line"><span>         1. 根据给定的主题，搜索最新的权威信息</span></span>
<span class="line"><span>         2. 整理关键数据和事实</span></span>
<span class="line"><span>         3. 标注信息来源</span></span>
<span class="line"><span>         输出格式：</span></span>
<span class="line"><span>         - 核心发现（3-5 条）</span></span>
<span class="line"><span>         - 关键数据（表格形式）</span></span>
<span class="line"><span>         - 信息来源列表</span></span>
<span class="line"><span>     tools:</span></span>
<span class="line"><span>       allow: [web_search, web_fetch, memory_write]</span></span>
<span class="line"><span>   # 撰稿人 — 内容创作</span></span>
<span class="line"><span>   - id: writer</span></span>
<span class="line"><span>     model: gpt-4o</span></span>
<span class="line"><span>     identity:</span></span>
<span class="line"><span>       name: &quot;撰稿人&quot;</span></span>
<span class="line"><span>       instructions: |</span></span>
<span class="line"><span>         你是一位经验丰富的撰稿人。你的工作是：</span></span>
<span class="line"><span>         1. 根据调研材料和主题要求撰写文章</span></span>
<span class="line"><span>         2. 确保逻辑清晰、论据充分、行文流畅</span></span>
<span class="line"><span>         3. 控制篇幅在 2000-3000 字</span></span>
<span class="line"><span>     tools:</span></span>
<span class="line"><span>       allow: [read, write, memory_search]</span></span>
<span class="line"><span>   # 审校员 — 质量把控</span></span>
<span class="line"><span>   - id: reviewer</span></span>
<span class="line"><span>     model: claude-sonnet-4-20250514</span></span>
<span class="line"><span>     identity:</span></span>
<span class="line"><span>       name: &quot;审校员&quot;</span></span>
<span class="line"><span>       instructions: |</span></span>
<span class="line"><span>         你是一位细心的审校员。你的工作是：</span></span>
<span class="line"><span>         1. 检查文章中的事实是否与调研数据一致</span></span>
<span class="line"><span>         2. 检查逻辑是否通顺、论述是否完整</span></span>
<span class="line"><span>         3. 检查是否有语法错误或用词不当</span></span>
<span class="line"><span>         输出格式：</span></span>
<span class="line"><span>         -  通过项</span></span>
<span class="line"><span>         - ⚠️ 建议修改项</span></span>
<span class="line"><span>         - ❌ 必须修改项</span></span>
<span class="line"><span>         - 总体评价和最终建议</span></span>
<span class="line"><span>     tools:</span></span>
<span class="line"><span>       allow: [read, memory_search]</span></span>
<span class="line"><span># 路由绑定</span></span>
<span class="line"><span>bindings:</span></span>
<span class="line"><span> - agentId: director</span></span>
<span class="line"><span>   match:</span></span>
<span class="line"><span>     channel: telegram</span></span></code></pre></div><p>我们通过一个流程，讲解整体的协作流程，当用户发送“帮我写一篇关于 AI 发展趋势的深度报告”时，整个协作流程如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/4.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当子 Agent 完成任务后，结果是通过 announce 回传机制 subagent-announce.ts 回传给</span></span></code></pre></div><p>父 Agent，详细的回传流程主要四步：</p><ol><li><p>子 Agent 完成所有推理循环后，输出最终文本</p></li><li><p>announce 模块将输出打包为“公告消息”</p></li><li><p>公告消息被发送到父 Agent 的消息队列</p></li><li><p>父 Agent 在下一轮推理中接收到公告，据此决定下一步动作</p></li></ol><p>子 Agent 的结果不是实时流式传回的，而是在子 Agent 完成后一次性回传。这意味着如果子Agent 的任务耗时较长，父 Agent 会等待。</p><p>子 Agent 权限 &lt; 父 Agent 权限，是 OpenClaw 强制执行的安全机制，最小权限原则。所有子Agent 一律禁止 gateway、sessions_send、memory_search 等控制面工具。在配置子 Agent时，tools.allow 应该只列出该角色真正需要的工具。比如审校员只需要 read 和memory_search，不需要 write（审校员不应该修改文件）和 exec（审校员不应该执行命令）。</p><p>当前设计是一次审校，更健壮的流程是支持多轮迭代，需要从从流水线到更复杂的系统，升级为多轮审校迭代，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/5.png" alt=""></a></p><p>不同类型的内容需求可以路由到不同的子 Agent，采用动态 Agent 选择：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/6.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总监 Agent 的 instructions 中可以描述这些规则，让 LLM 根据需求类型自动选择合适的</span></span></code></pre></div><p>子 Agent 组合。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本节课我们的核心知识点如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/OpenClaw%E6%A0%B8%E5%BF%83%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E6%88%98/images/31/7.png" alt=""></a></p><p>到目前为止你现在能做到：</p><ul><li>设计多 Agent 协作的系统架构</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配置父 Agent 的 subagents 白名单和默认模型</span></span></code></pre></div><ul><li><p>为每个子 Agent 配置最小必要的工具权限</p></li><li><p>理解 announce 回传机制和循环检测的保护作用</p></li></ul><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>构建一个“一人开发团队”多 Agent 系统，包含四个角色：需求分析师、编码员、测试员、文档员。要求：通过父 Agent 统一调度，每个子 Agent 有差异化的工具权限和模型配置。</p><p>欢迎你在留言区与我交流！如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,48)])])}const h=s(t,[["render",l]]);export{u as __pageData,h as default};
